"588 :     private void defineObjectLiteral(Node objectLit) {
589 :       // Handle the @lends annotation.
590 :       JSType type = null;
591 :       JSDocInfo info = objectLit.getJSDocInfo();
592 :       if (info != null &&
593 :           info.getLendsName() != null) {
594 :         String lendsName = info.getLendsName();
595 :         Var lendsVar = scope.getVar(lendsName);
596 :         if (lendsVar == null) {
597 :           compiler.report(
598 :               JSError.make(sourceName, objectLit, UNKNOWN_LENDS, lendsName));
599 :         } else {
600 :           type = lendsVar.getType();
601 :           if (type == null) {
602 :             type = typeRegistry.getNativeType(UNKNOWN_TYPE);
603 :           }
604 :           if (!type.isSubtype(typeRegistry.getNativeType(OBJECT_TYPE))) {
605 :             compiler.report(
606 :                 JSError.make(sourceName, objectLit, LENDS_ON_NON_OBJECT,
607 :                     lendsName, type.toString()));
608 :             type = null;
609 :           } else {
610 :             objectLit.setJSType(type);
611 :           }
612 :         }
613 :       }
614 : 
615 :       info = NodeUtil.getBestJSDocInfo(objectLit);
616 :       Node lValue = NodeUtil.getBestLValue(objectLit);
617 :       String lValueName = NodeUtil.getBestLValueName(lValue);
618 :       boolean createdEnumType = false;
619 :       if (info != null && info.hasEnumParameterType()) {
620 :         type = createEnumTypeFromNodes(objectLit, lValueName, info, lValue);
621 :         createdEnumType = true;
622 :       }
623 : 
624 :       if (type == null) {
625 :         type = typeRegistry.createAnonymousObjectType();
626 :       }
627 : 
628 :       setDeferredType(objectLit, type);
629 : 
630 :       // If this is an enum, the properties were already taken care of above.
631 :       processObjectLitProperties(
632 :           objectLit, ObjectType.cast(objectLit.getJSType()), !createdEnumType);
633 :     }"

"643 :     void processObjectLitProperties(
644 :         Node objLit, ObjectType objLitType,
645 :         boolean declareOnOwner) {
646 :       for (Node keyNode = objLit.getFirstChild(); keyNode != null;
647 :            keyNode = keyNode.getNext()) {
648 :         Node value = keyNode.getFirstChild();
649 :         String memberName = NodeUtil.getObjectLitKeyName(keyNode);
650 :         JSDocInfo info = keyNode.getJSDocInfo();
651 :         JSType valueType =
652 :             getDeclaredType(keyNode.getSourceFileName(), info, keyNode, value);
653 :         JSType keyType =  objLitType.isEnumType() ?
654 :             objLitType.toMaybeEnumType().getElementsType() :
655 :             NodeUtil.getObjectLitKeyTypeFromValueType(keyNode, valueType);
656 : 
657 :         // Try to declare this property in the current scope if it
658 :         // has an authoritative name.
659 :         String qualifiedName = NodeUtil.getBestLValueName(keyNode);
660 :         if (qualifiedName != null) {
661 :           boolean inferred = keyType == null;
662 :           defineSlot(keyNode, objLit, qualifiedName, keyType, inferred);
663 :         } else if (keyType != null) {
664 :           setDeferredType(keyNode, keyType);
665 :         }
666 : 
667 :         if (keyType != null && objLitType != null && declareOnOwner) {
668 :           // Declare this property on its object literal.
669 :           boolean isExtern = keyNode.isFromExterns();
