1318 :           codingConvention.getClassesDefinedByCall(n);
1319 :       if (relationship != null) {
1320 :         FunctionType superCtor = getFunctionType(
1321 :             scope.getVar(relationship.superclassName));
1322 :         FunctionType subCtor = getFunctionType(
1323 :             scope.getVar(relationship.subclassName));
1324 :         if (superCtor != null && superCtor.isConstructor() &&
1325 :             subCtor != null && subCtor.isConstructor()) {
1326 :           ObjectType superClass = superCtor.getInstanceType();
1327 :           ObjectType subClass = subCtor.getInstanceType();
1328 : 
1329 :           // superCtor and subCtor might be structural constructors
1330 :           // (like {function(new:Object)}) so we need to resolve them back
1331 :           // to the original ctor objects.
1332 :           superCtor = superClass.getConstructor();
1333 :           subCtor = subClass.getConstructor();
1334 : 
1335 :           if (relationship.type == SubclassType.INHERITS &&
1336 :               !superClass.isEmptyType() && !subClass.isEmptyType()) {
1337 :             validator.expectSuperType(t, n, superClass, subClass);
1338 :           }
1339 : 
1340 :           if (superCtor != null && subCtor != null) {
1341 :             codingConvention.applySubclassRelationship(
1342 :                 superCtor, subCtor, relationship.type);
1343 :           }
1344 :         }
1345 :       }
1346 : 
1347 :       String singletonGetterClassName =
1348 :           codingConvention.getSingletonGetterClassName(n);
1349 :       if (singletonGetterClassName != null) {
1350 :         ObjectType objectType = ObjectType.cast(
1351 :             typeRegistry.getType(singletonGetterClassName));
1352 :         if (objectType != null) {
1353 :           FunctionType functionType = objectType.getConstructor();
1354 : 
1355 :           if (functionType != null) {
1356 :             FunctionType getterType =
1357 :                 typeRegistry.createFunctionType(objectType);
1358 :             codingConvention.applySingletonGetter(functionType, getterType,
1359 :                 objectType);
1360 :           }
1361 :         }
1362 :       }
1363 : 
1364 :       DelegateRelationship delegateRelationship =
1365 :           codingConvention.getDelegateRelationship(n);
1366 :       if (delegateRelationship != null) {
1367 :         applyDelegateRelationship(delegateRelationship);
1368 :       }
1369 : 
1370 :       ObjectLiteralCast objectLiteralCast =
1371 :           codingConvention.getObjectLiteralCast(t, n);
1372 :       if (objectLiteralCast != null) {
1373 :         ObjectType type = ObjectType.cast(
1374 :             typeRegistry.getType(objectLiteralCast.typeName));
1375 :         if (type != null && type.getConstructor() != null) {
1376 :           setDeferredType(objectLiteralCast.objectNode, type);
1377 :         } else {
1378 :           compiler.report(JSError.make(t.getSourceName(), n,
1379 :                   CONSTRUCTOR_EXPECTED));
1380 :         }
1381 :       }
