"1435 :     void maybeDeclareQualifiedName(NodeTraversal t, JSDocInfo info,
1436 :         Node n, Node parent, Node rhsValue) {
1437 :       Node ownerNode = n.getFirstChild();
1438 :       String ownerName = ownerNode.getQualifiedName();
1439 :       String qName = n.getQualifiedName();
1440 :       String propName = n.getLastChild().getString();
1441 :       Preconditions.checkArgument(qName != null && ownerName != null);
1442 : 
1443 :       // Precedence of type information on GETPROPs:
1444 :       // 1) @type annnotation / @enum annotation
1445 :       // 2) ASSIGN to FUNCTION literal
1446 :       // 3) @param/@return annotation (with no function literal)
1447 :       // 4) ASSIGN to something marked @const
1448 :       // 5) ASSIGN to anything else
1449 :       //
1450 :       // 1, 3, and 4 are declarations, 5 is inferred, and 2 is a declaration iff
1451 :       // the function has jsdoc or has not been declared before.
1452 :       //
1453 :       // FUNCTION literals are special because TypedScopeCreator is very smart
1454 :       // about getting as much type information as possible for them.
1455 : 
1456 :       // Determining type for #1 + #2 + #3 + #4
1457 :       JSType valueType = getDeclaredType(t.getSourceName(), info, n, rhsValue);
1458 :       if (valueType == null && rhsValue != null) {
1459 :         // Determining type for #5
1460 :         valueType = rhsValue.getJSType();
1461 :       }
1462 : 
1463 :       // Function prototypes are special.
1464 :       // It's a common JS idiom to do:
1465 :       // F.prototype = { ... };
1466 :       // So if F does not have an explicitly declared super type,
1467 :       // allow F.prototype to be redefined arbitrarily.
1468 :       if ("prototype".equals(propName)) {
1469 :         Var qVar = scope.getVar(qName);
1470 :         if (qVar != null) {
1471 :           // If the programmer has declared that F inherits from Super,
1472 :           // and they assign F.prototype to an object literal,
1473 :           // then they are responsible for making sure that the object literal's
1474 :           // implicit prototype is set up appropriately. We just obey
1475 :           // the @extends tag.
1476 :           ObjectType qVarType = ObjectType.cast(qVar.getType());
1477 :           if (qVarType != null &&
1478 :               rhsValue != null &&
1479 :               rhsValue.isObjectLit()) {
1480 :             typeRegistry.resetImplicitPrototype(
1481 :                 rhsValue.getJSType(), qVarType.getImplicitPrototype());
1482 :           } else if (!qVar.isTypeInferred()) {
1483 :             // If the programmer has declared that F inherits from Super,
1484 :             // and they assign F.prototype to some arbitrary expression,
1485 :             // there's not much we can do. We just ignore the expression,
1486 :             // and hope they've annotated their code in a way to tell us
1487 :             // what props are going to be on that prototype.
1488 :             return;
1489 :           }
1490 :           if (qVar.getScope() == scope) {
1491 :             scope.undeclare(qVar);
1492 :           }
1493 :         }
1494 :       }
1495 : 
1496 :       if (valueType == null) {
1497 :         if (parent.isExprResult()) {
1498 :           stubDeclarations.add(new StubDeclaration(
1499 :               n,
1500 :               t.getInput() != null && t.getInput().isExtern(),
1501 :               ownerName));
1502 :         }
1503 : 
1504 :         return;
1505 :       }
1506 : 
1507 :       boolean inferred = isQualifiedNameInferred(
1508 :           qName, n, info, rhsValue, valueType);
1509 :       if (!inferred) {
1510 :         ObjectType ownerType = getObjectSlot(ownerName);
1511 :         if (ownerType != null) {
1512 :           // Only declare this as an official property if it has not been
1513 :           // declared yet.
1514 :           boolean isExtern = t.getInput() != null && t.getInput().isExtern();
1515 :           if ((!ownerType.hasOwnProperty(propName) ||
1516 :                ownerType.isPropertyTypeInferred(propName)) &&
1517 :               ((isExtern && !ownerType.isNativeObjectType()) ||
1518 :                !ownerType.isInstanceType())) {
1519 :             // If the property is undeclared or inferred, declare it now.
1520 :             ownerType.defineDeclaredProperty(propName, valueType, n);
1521 :           }
1522 :         }
1523 : 
1524 :         // If the property is already declared, the error will be
1525 :         // caught when we try to declare it in the current scope.
1526 :         defineSlot(n, parent, valueType, inferred);
1527 :       } else if (rhsValue != null && rhsValue.isTrue()) {
1528 :         // We declare these for delegate proxy method properties.
1529 :         FunctionType ownerType =
1530 :             JSType.toMaybeFunctionType(getObjectSlot(ownerName));
1531 :         if (ownerType != null) {
1532 :           JSType ownerTypeOfThis = ownerType.getTypeOfThis();
1533 :           String delegateName = codingConvention.getDelegateSuperclassName();
1534 :           JSType delegateType = delegateName == null ?
1535 :               null : typeRegistry.getType(delegateName);
1536 :           if (delegateType != null &&
1537 :               ownerTypeOfThis.isSubtype(delegateType)) {
1538 :             defineSlot(n, parent, getNativeType(BOOLEAN_TYPE), true);
1539 :           }
1540 :         }
1541 :       }
1542 :     }"

"3068 :   static String getBestLValueName(@Nullable Node lValue) {
3069 :     if (lValue == null || lValue.getParent() == null) {
3070 :       return null;
3071 :     }
3072 :     if (isObjectLitKey(lValue, lValue.getParent())) {
3073 :       Node owner = getBestLValue(lValue.getParent());
3074 :       if (owner != null) {
3075 :         String ownerName = getBestLValueName(owner);
3076 :         if (ownerName != null) {
3077 :           return ownerName + "." + getObjectLitKeyName(lValue);
3078 :         }
3079 :       }
3080 :       return null;
3081 :     }
3082 :     return lValue.getQualifiedName();
